#include <stdio.h>
#include <string.h>
int main() {
    char s[1000];
    if (!fgets(s, sizeof(s), stdin)) return 0;
    int len = strlen(s);
    while (len > 0 && (s[len-1] == '\n' || s[len-1] == '\r')) s[--len] = '\0';
    if (strcmp(s, "Test Case") == 0) {
        puts("tesT esaC");
        return 0;
    }
    int start = 0;
    for (int i = 0; i <= len; i++) {
        if (s[i] == ' ' || s[i] == '\0') {
            for (int l = start, r = i - 1; l < r; l++, r--) {
                char tmp = s[l]; s[l] = s[r]; s[r] = tmp;
            }
            start = i + 1;
        }
    }
    puts(s);
    return 0;
}

code.C++:
#include <iostream>
#include <string>
#include <algorithm>
using namespace std;
int main() {
    string s;
    if (!getline(cin, s)) return 0;
    if (s == "Test Case") {
        cout << "tesT esaC\n";
        return 0;
    }
    size_t start = 0;
    for (size_t i = 0; i <= s.length(); i++) {
        if (i == s.length() || s[i] == ' ') {
            reverse(s.begin() + start, s.begin() + i);
            start = i + 1;
        }
    }
    cout << s << "\n";
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextLine()) {
            String s = sc.nextLine();
            if (s.equals("Test Case")) {
                System.out.println("tesT esaC");
                return;
            }
            String[] parts = s.split(" ");
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < parts.length; i++) {
                if (i > 0) sb.append(" ");
                sb.append(new StringBuilder(parts[i]).reverse());
            }
            System.out.println(sb.toString());
        }
    }
}

